package com.aistock.notification.alert;
import static com.aistock.notification.alert.AlertEvaluationRecords.*;import com.aistock.common.BusinessException;import com.fasterxml.jackson.databind.*;import java.time.*;import java.util.*;import java.sql.Timestamp;import java.security.MessageDigest;import org.springframework.http.HttpStatus;
/** Uses the existing owner guard before operation/rule locks, matching rule updates. */
final class AlertEvaluationStore {
 private final AlertRuleRepository repo;private final Clock clock;private final ObjectMapper mapper=new ObjectMapper().findAndRegisterModules().disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS);
 AlertEvaluationStore(AlertRuleRepository repo,Clock clock){this.repo=repo;this.clock=clock;}
 record Start(EvaluationReceipt receipt,boolean dispatch){}
 Start begin(UUID owner,EvaluateRequest r){return repo.locked(owner,()->{boolean inserted=true;try{repo.jdbc().update("insert into alert_evaluation_operation(operation_id,owner_id,request_hash,rule_id,rule_revision,evidence_id,lease_until,state,created_at) values(?,?,?,?,?,?,?,'RUNNING',?)",r.operationId().toString(),owner.toString(),hash(r),r.ruleId().toString(),r.revision(),r.evidenceId().toString(),Timestamp.from(r.leaseUntil()),Timestamp.from(clock.instant()));}catch(org.springframework.dao.DuplicateKeyException duplicate){inserted=false;}var row=repo.jdbc().queryForMap("select * from alert_evaluation_operation where operation_id=? for update",r.operationId().toString());if(!owner.toString().equals(row.get("owner_id"))||!hash(r).equals(row.get("request_hash")))throw error("ALERT_OPERATION_CONFLICT",HttpStatus.CONFLICT);var receipt=expire(r.operationId(),row);return new Start(receipt,inserted&&"RUNNING".equals(receipt.state()));});}
 EvaluationReceipt receipt(UUID id){var rows=repo.jdbc().queryForList("select owner_id from alert_evaluation_operation where operation_id=?",id.toString());if(rows.isEmpty())throw error("RESOURCE_NOT_FOUND",HttpStatus.NOT_FOUND);return repo.locked(UUID.fromString((String)rows.get(0).get("owner_id")),()->expire(id,repo.jdbc().queryForMap("select * from alert_evaluation_operation where operation_id=? for update",id.toString())));}
 EvaluationReceipt finish(UUID owner,EvaluateRequest r,java.util.function.Supplier<EvaluationReceipt> action){return repo.locked(owner,()->{var row=repo.jdbc().queryForMap("select * from alert_evaluation_operation where operation_id=? for update",r.operationId().toString());var current=expire(r.operationId(),row);if(!"RUNNING".equals(current.state()))return current;var result=action.get();if(!clock.instant().isBefore(r.leaseUntil()))throw error("ATTEMPT_EXPIRED",HttpStatus.CONFLICT);save(result);return result;});}
 private EvaluationReceipt expire(UUID id,Map<String,Object> row){if("RUNNING".equals(row.get("state"))&&!clock.instant().isBefore(((Timestamp)row.get("lease_until")).toInstant())){var expired=new EvaluationReceipt(id,"FAILED",null,"ATTEMPT_EXPIRED");save(expired);return expired;}return new EvaluationReceipt(id,(String)row.get("state"),row.get("trigger_id")==null?null:UUID.fromString((String)row.get("trigger_id")),(String)row.get("reason_code"));}
 void checkedTradeDate(UUID operationId,LocalDate tradeDate){
  repo.jdbc().update("update alert_evaluation_operation set checked_trade_date=? where operation_id=? and state='RUNNING'",tradeDate,operationId.toString());
 }
 private void save(EvaluationReceipt r){repo.jdbc().update("update alert_evaluation_operation set state=?,fencing_revision=fencing_revision+1,trigger_id=?,reason_code=?,finished_at=? where operation_id=? and state='RUNNING'",r.state(),r.triggerId()==null?null:r.triggerId().toString(),r.reasonCode(),Timestamp.from(clock.instant()),r.operationId().toString());}
 String useInput(UUID owner,EvaluateRequest request){return repo.locked(owner,()->{var row=repo.jdbc().queryForMap("select * from alert_evaluation_operation where operation_id=? for update",request.operationId().toString());if(!owner.toString().equals(row.get("owner_id"))||!hash(request).equals(row.get("request_hash"))||!"RUNNING".equals(expire(request.operationId(),row).state()))throw AlertMarketUseClient.unavailable();return repo.jdbc().queryForObject("select instrument_id from alert_rule where rule_id=? and user_id=?",String.class,request.ruleId().toString(),owner.toString());});}
 JsonNode terminal(UUID operation){var found=repo.jdbc().queryForList("select owner_id from alert_evaluation_operation where operation_id=?",String.class,operation.toString());if(found.size()!=1)throw AlertMarketUseClient.unavailable();return repo.locked(UUID.fromString(found.get(0)),()->{var row=repo.jdbc().queryForMap("select * from alert_evaluation_operation where operation_id=? for update",operation.toString());var terminal=expire(operation,row);if("RUNNING".equals(terminal.state()))throw AlertMarketUseClient.unavailable();row=repo.jdbc().queryForMap("select * from alert_evaluation_operation where operation_id=?",operation.toString());if(row.get("finished_at")==null)throw AlertMarketUseClient.invalid();var out=mapper.createObjectNode();out.put("state","FAILED".equals(terminal.state())?"FAILED":"SUCCEEDED").put("terminalAt",((Timestamp)row.get("finished_at")).toInstant().toString()).put("fencingRevision",row.get("fencing_revision").toString()).put("resultIdentity",terminal.triggerId()==null?operation.toString():terminal.triggerId().toString());return out;});}
 String json(Object value){try{return mapper.writeValueAsString(value);}catch(Exception error){throw error("ALERT_RECORD_INVALID",HttpStatus.SERVICE_UNAVAILABLE);}}
 private String hash(Object value){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(json(value).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception error){throw error("ALERT_RECORD_INVALID",HttpStatus.SERVICE_UNAVAILABLE);}}
 static BusinessException error(String code,HttpStatus status){return new BusinessException(code,"预警评价暂未完成或请求无效",status);}
}
